func putEasing(o *rt.Tape, v Easing) {
	switch x := v.(type) {
	case EasingKind:
		_ = x
		o.U16(uint16(x))
	case EasingCubicBezier:
		_ = x
		o.U16(5)
		o.F32(x.X1)
		o.F32(x.Y1)
		o.F32(x.X2)
		o.F32(x.Y2)
	case EasingSteps:
		_ = x
		o.U16(6)
		rt.PutNonzero(o, uint64(x.Count), 4)
		o.U16(uint16(x.Position))
	case EasingLinearStops:
		_ = x
		o.U16(7)
		o.U32(uint32(len(x.Value)))
		for _, x0 := range x.Value {
			o.F32(x0.V0)
			o.F32(x0.V1)
		}
	case EasingCustom:
		_ = x
		o.U16(8)
		rt.PutExpr(o, x.Value, 1)
	default:
		rt.Stop("a nil or unknown gk.Easing was given to a builder: give one of its variants (gk.Easing...)")
	}
}

