func rdFileDropEvent(r *rt.Reader) FileDropEvent {
	switch r.U16() {
	case 0:
		return FileDropEventEntered{Position: rdGpuiPoint(r), Paths: rt.RdList(r, func(r *rt.Reader) string { return r.Str() })}
	case 1:
		return FileDropEventPending{Position: rdGpuiPoint(r)}
	case 2:
		return FileDropEventSubmit{Position: rdGpuiPoint(r)}
	case 3:
		return FileDropEventExited{}
	case 4:
		return FileDropEventEnded{}
	}
	rt.Stop("an event of type FileDropEvent arrived with a variant this package does not know: the library and the package disagree. Build the app against the go/ folder of the download its libgpuikit.so came from")
	return nil
}

func rdBackGestureEvent(r *rt.Reader) (v BackGestureEvent) {
	v.Phase = BackGesturePhase(r.U16())
	v.StartPosition = rdGpuiPoint(r)
	v.Progress = r.F32()
	return
}

